package com.parion.aidat;
import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import java.text.*;import java.util.*;
public class DbHelper extends SQLiteOpenHelper{
 static final int VERSION=2; final SimpleDateFormat iso=new SimpleDateFormat("yyyy-MM-dd",Locale.US);
 public DbHelper(Context c){super(c,"parion_aidat.db",null,VERSION);iso.setLenient(false);}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE athletes(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,birthYear INTEGER DEFAULT 0,birthDate TEXT,tckn TEXT,startDate TEXT,athletePhone TEXT,parent TEXT,phone TEXT,motherName TEXT,motherPhone TEXT,fatherName TEXT,fatherPhone TEXT,school TEXT,classBranch TEXT,groupName TEXT,monthlyFee REAL NOT NULL DEFAULT 0,scholarship INTEGER NOT NULL DEFAULT 0,illnesses TEXT,notes TEXT,leaveDate TEXT,leaveReason TEXT,photoUri TEXT,tshirtQty INTEGER DEFAULT 0,jerseyQty INTEGER DEFAULT 0,tracksuitQty INTEGER DEFAULT 0,active INTEGER NOT NULL DEFAULT 1)");d.execSQL("CREATE TABLE payments(id INTEGER PRIMARY KEY AUTOINCREMENT,athleteId INTEGER NOT NULL,year INTEGER NOT NULL,month INTEGER NOT NULL,amount REAL NOT NULL,paymentDate TEXT,method TEXT,note TEXT,UNIQUE(athleteId,year,month))");d.execSQL("CREATE TABLE fee_history(id INTEGER PRIMARY KEY AUTOINCREMENT,athleteId INTEGER NOT NULL,effectiveDate TEXT NOT NULL,fee REAL NOT NULL,scholarship INTEGER NOT NULL DEFAULT 0)");d.execSQL("CREATE TABLE groups(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,isSportsSchool INTEGER NOT NULL DEFAULT 1)");d.execSQL("CREATE TABLE group_schedule(id INTEGER PRIMARY KEY AUTOINCREMENT,groupName TEXT NOT NULL,weekday INTEGER NOT NULL,effectiveFrom TEXT NOT NULL)");d.execSQL("CREATE TABLE attendance(id INTEGER PRIMARY KEY AUTOINCREMENT,athleteId INTEGER NOT NULL,groupName TEXT NOT NULL,trainingDate TEXT NOT NULL,present INTEGER NOT NULL DEFAULT 1,UNIQUE(athleteId,trainingDate))");d.execSQL("CREATE TABLE inventory(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,stock INTEGER NOT NULL DEFAULT 0,buyPrice REAL NOT NULL DEFAULT 0,sellPrice REAL NOT NULL DEFAULT 0)");d.execSQL("CREATE TABLE inventory_tx(id INTEGER PRIMARY KEY AUTOINCREMENT,itemId INTEGER NOT NULL,txDate TEXT NOT NULL,qty INTEGER NOT NULL,type TEXT NOT NULL,buyUnit REAL NOT NULL DEFAULT 0,sellUnit REAL NOT NULL DEFAULT 0,athleteId INTEGER)");seed(d);}
 public void onUpgrade(SQLiteDatabase d,int o,int n){if(o<2){String[] a={"ALTER TABLE athletes ADD COLUMN birthDate TEXT","ALTER TABLE athletes ADD COLUMN tckn TEXT","ALTER TABLE athletes ADD COLUMN startDate TEXT","ALTER TABLE athletes ADD COLUMN athletePhone TEXT","ALTER TABLE athletes ADD COLUMN motherName TEXT","ALTER TABLE athletes ADD COLUMN motherPhone TEXT","ALTER TABLE athletes ADD COLUMN fatherName TEXT","ALTER TABLE athletes ADD COLUMN fatherPhone TEXT","ALTER TABLE athletes ADD COLUMN school TEXT","ALTER TABLE athletes ADD COLUMN classBranch TEXT","ALTER TABLE athletes ADD COLUMN scholarship INTEGER NOT NULL DEFAULT 0","ALTER TABLE athletes ADD COLUMN illnesses TEXT","ALTER TABLE athletes ADD COLUMN notes TEXT","ALTER TABLE athletes ADD COLUMN leaveDate TEXT","ALTER TABLE athletes ADD COLUMN leaveReason TEXT","ALTER TABLE athletes ADD COLUMN photoUri TEXT","ALTER TABLE athletes ADD COLUMN tshirtQty INTEGER DEFAULT 0","ALTER TABLE athletes ADD COLUMN jerseyQty INTEGER DEFAULT 0","ALTER TABLE athletes ADD COLUMN tracksuitQty INTEGER DEFAULT 0"};for(String s:a)try{d.execSQL(s);}catch(Exception e){}d.execSQL("CREATE TABLE IF NOT EXISTS fee_history(id INTEGER PRIMARY KEY AUTOINCREMENT,athleteId INTEGER NOT NULL,effectiveDate TEXT NOT NULL,fee REAL NOT NULL,scholarship INTEGER NOT NULL DEFAULT 0)");d.execSQL("CREATE TABLE IF NOT EXISTS groups(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,isSportsSchool INTEGER NOT NULL DEFAULT 1)");d.execSQL("CREATE TABLE IF NOT EXISTS group_schedule(id INTEGER PRIMARY KEY AUTOINCREMENT,groupName TEXT NOT NULL,weekday INTEGER NOT NULL,effectiveFrom TEXT NOT NULL)");d.execSQL("CREATE TABLE IF NOT EXISTS attendance(id INTEGER PRIMARY KEY AUTOINCREMENT,athleteId INTEGER NOT NULL,groupName TEXT NOT NULL,trainingDate TEXT NOT NULL,present INTEGER NOT NULL DEFAULT 1,UNIQUE(athleteId,trainingDate))");d.execSQL("CREATE TABLE IF NOT EXISTS inventory(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,stock INTEGER NOT NULL DEFAULT 0,buyPrice REAL NOT NULL DEFAULT 0,sellPrice REAL NOT NULL DEFAULT 0)");d.execSQL("CREATE TABLE IF NOT EXISTS inventory_tx(id INTEGER PRIMARY KEY AUTOINCREMENT,itemId INTEGER NOT NULL,txDate TEXT NOT NULL,qty INTEGER NOT NULL,type TEXT NOT NULL,buyUnit REAL NOT NULL DEFAULT 0,sellUnit REAL NOT NULL DEFAULT 0,athleteId INTEGER)");seed(d);}}
 void seed(SQLiteDatabase d){for(String g:new String[]{"Spor Okulu 1","Spor Okulu 2","Spor Okulu 3","Spor Okulu 4"})d.execSQL("INSERT OR IGNORE INTO groups(name,isSportsSchool) VALUES(?,1)",new Object[]{g});for(String i:new String[]{"Tişört","Forma","Eşofman"})d.execSQL("INSERT OR IGNORE INTO inventory(name,stock,buyPrice,sellPrice) VALUES(?,0,0,0)",new Object[]{i});}
 public long addAthlete(String name,String bd,String tc,String sd,String ap,String mn,String mp,String fn,String fp,String school,String cb,String group,double fee,boolean burs,String ill,String notes,String ld,String lr,String photo,int tq,int jq,int eq){ContentValues v=new ContentValues();v.put("name",name);v.put("birthDate",bd);v.put("tckn",tc);v.put("startDate",sd);v.put("athletePhone",ap);v.put("motherName",mn);v.put("motherPhone",mp);v.put("fatherName",fn);v.put("fatherPhone",fp);v.put("school",school);v.put("classBranch",cb);v.put("groupName",group);v.put("monthlyFee",burs?0:fee);v.put("scholarship",burs?1:0);v.put("illnesses",ill);v.put("notes",notes);v.put("leaveDate",ld);v.put("leaveReason",lr);v.put("photoUri",photo);v.put("tshirtQty",tq);v.put("jerseyQty",jq);v.put("tracksuitQty",eq);v.put("active",ld==null||ld.isEmpty()?1:0);long id=getWritableDatabase().insert("athletes",null,v);if(id>0)updateFee(id,fee,burs,sd==null||sd.isEmpty()?"1900-01-01":sd);return id;}
 public Cursor athletes(){return getReadableDatabase().rawQuery("SELECT * FROM athletes ORDER BY active DESC,name COLLATE NOCASE",null);}public Cursor activeAthletes(){return getReadableDatabase().rawQuery("SELECT * FROM athletes WHERE active=1 ORDER BY name COLLATE NOCASE",null);}public Cursor athletesByGroup(String g){return getReadableDatabase().rawQuery("SELECT * FROM athletes WHERE active=1 AND groupName=? ORDER BY name COLLATE NOCASE",new String[]{g});}public Cursor searchAthletes(String q){return getReadableDatabase().rawQuery("SELECT * FROM athletes WHERE name LIKE ? OR tckn LIKE ? ORDER BY active DESC,name COLLATE NOCASE",new String[]{q+"%",q+"%"});}public Cursor athlete(long id){return getReadableDatabase().rawQuery("SELECT * FROM athletes WHERE id=?",new String[]{""+id});}public Cursor groups(boolean only){return getReadableDatabase().rawQuery("SELECT * FROM groups"+(only?" WHERE isSportsSchool=1":"")+" ORDER BY name",null);}public void addGroup(String n,boolean s){ContentValues v=new ContentValues();v.put("name",n);v.put("isSportsSchool",s?1:0);getWritableDatabase().insertWithOnConflict("groups",null,v,SQLiteDatabase.CONFLICT_IGNORE);}public boolean deleteGroup(String n){Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM athletes WHERE groupName=? AND active=1",new String[]{n});c.moveToFirst();int x=c.getInt(0);c.close();if(x>0)return false;SQLiteDatabase d=getWritableDatabase();d.delete("group_schedule","groupName=?",new String[]{n});d.delete("attendance","groupName=?",new String[]{n});return d.delete("groups","name=?",new String[]{n})>0;}
 public boolean isPaid(long id,int y,int m){Cursor c=getReadableDatabase().rawQuery("SELECT id FROM payments WHERE athleteId=? AND year=? AND month=?",new String[]{""+id,""+y,""+m});boolean b=c.moveToFirst();c.close();return b;}public void markPaid(long id,int y,int m,double a,String meth){ContentValues v=new ContentValues();v.put("athleteId",id);v.put("year",y);v.put("month",m);v.put("amount",a);v.put("paymentDate",iso.format(new Date()));v.put("method",meth);getWritableDatabase().insertWithOnConflict("payments",null,v,SQLiteDatabase.CONFLICT_REPLACE);}public void removePayment(long id,int y,int m){getWritableDatabase().delete("payments","athleteId=? AND year=? AND month=?",new String[]{""+id,""+y,""+m});}public double collected(int y,int m){Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(SUM(amount),0) FROM payments WHERE year=? AND month=?",new String[]{""+y,""+m});c.moveToFirst();double x=c.getDouble(0);c.close();return x;}public Cursor paymentsFor(long id){return getReadableDatabase().rawQuery("SELECT * FROM payments WHERE athleteId=? ORDER BY year DESC,month DESC",new String[]{""+id});}
 Date parse(String s){try{return iso.parse(s);}catch(Exception e){return null;}}Calendar ms(Calendar c){Calendar x=(Calendar)c.clone();x.set(Calendar.DAY_OF_MONTH,1);return x;}public String dueDate(long id,int y,int m){Cursor c=athlete(id);if(!c.moveToFirst()){c.close();return null;}Date d=parse(c.getString(c.getColumnIndexOrThrow("startDate")));c.close();if(d==null)return String.format(Locale.US,"%04d-%02d-01",y,m);Calendar first=Calendar.getInstance();first.setTime(d);first.add(Calendar.MONTH,1);Calendar t=Calendar.getInstance();t.clear();t.set(y,m-1,1);if(t.before(ms(first)))return null;t.set(Calendar.DAY_OF_MONTH,Math.min(first.get(Calendar.DAY_OF_MONTH),t.getActualMaximum(Calendar.DAY_OF_MONTH)));return iso.format(t.getTime());}public double feeForDate(long id,String date){Cursor c=getReadableDatabase().rawQuery("SELECT fee,scholarship FROM fee_history WHERE athleteId=? AND effectiveDate<=? ORDER BY effectiveDate DESC,id DESC LIMIT 1",new String[]{""+id,date});if(c.moveToFirst()){double x=c.getInt(1)==1?0:c.getDouble(0);c.close();return x;}c.close();Cursor a=athlete(id);double x=0;if(a.moveToFirst())x=a.getInt(a.getColumnIndexOrThrow("scholarship"))==1?0:a.getDouble(a.getColumnIndexOrThrow("monthlyFee"));a.close();return x;}public double expectedForMonth(long id,int y,int m){String d=dueDate(id,y,m);return d==null?0:feeForDate(id,d);}public double expectedTotal(int y,int m){double x=0;Cursor c=activeAthletes();while(c.moveToNext())x+=expectedForMonth(c.getLong(c.getColumnIndexOrThrow("id")),y,m);c.close();return x;}public int unpaidCount(int y,int m){int n=0;Cursor c=activeAthletes();while(c.moveToNext()){long id=c.getLong(c.getColumnIndexOrThrow("id"));if(expectedForMonth(id,y,m)>0&&!isPaid(id,y,m))n++;}c.close();return n;}
 public void updateFee(long id,double fee,boolean burs,String date){ContentValues h=new ContentValues();h.put("athleteId",id);h.put("effectiveDate",date);h.put("fee",burs?0:fee);h.put("scholarship",burs?1:0);getWritableDatabase().insert("fee_history",null,h);ContentValues v=new ContentValues();v.put("monthlyFee",burs?0:fee);v.put("scholarship",burs?1:0);getWritableDatabase().update("athletes",v,"id=?",new String[]{""+id});}public int bulkUpdateFee(String g,double old,double ne,String date){Cursor c=getReadableDatabase().rawQuery("SELECT id FROM athletes WHERE active=1 AND groupName=? AND ABS(monthlyFee-?)<.01 AND scholarship=0",new String[]{g,""+old});ArrayList<Long>a=new ArrayList<>();while(c.moveToNext())a.add(c.getLong(0));c.close();for(long id:a)updateFee(id,ne,false,date);return a.size();}public void updateEquipment(long id,int t,int j,int e){ContentValues v=new ContentValues();v.put("tshirtQty",t);v.put("jerseyQty",j);v.put("tracksuitQty",e);getWritableDatabase().update("athletes",v,"id=?",new String[]{""+id});}
 public int[] scheduleDays(String g){Cursor c=getReadableDatabase().rawQuery("SELECT weekday FROM group_schedule WHERE groupName=? ORDER BY weekday",new String[]{g});ArrayList<Integer>a=new ArrayList<>();while(c.moveToNext())a.add(c.getInt(0));c.close();int[]x=new int[a.size()];for(int i=0;i<a.size();i++)x[i]=a.get(i);return x;}public void setSchedule(String g,boolean[] s){SQLiteDatabase d=getWritableDatabase();d.delete("group_schedule","groupName=?",new String[]{g});String today=iso.format(new Date());for(int i=0;i<s.length;i++)if(s[i]){ContentValues v=new ContentValues();v.put("groupName",g);v.put("weekday",i+2>7?1:i+2);v.put("effectiveFrom",today);d.insert("group_schedule",null,v);}}public ArrayList<String> trainingDates(String g,int y,int m){HashSet<Integer>s=new HashSet<>();for(int d:scheduleDays(g))s.add(d);ArrayList<String>o=new ArrayList<>();Calendar c=Calendar.getInstance();c.clear();c.set(y,m-1,1);for(int d=1;d<=c.getActualMaximum(Calendar.DAY_OF_MONTH);d++){c.set(Calendar.DAY_OF_MONTH,d);if(s.contains(c.get(Calendar.DAY_OF_WEEK)))o.add(iso.format(c.getTime()));}return o;}public void saveAttendance(long id,String g,String date,boolean p){ContentValues v=new ContentValues();v.put("athleteId",id);v.put("groupName",g);v.put("trainingDate",date);v.put("present",p?1:0);getWritableDatabase().insertWithOnConflict("attendance",null,v,SQLiteDatabase.CONFLICT_REPLACE);}public boolean attendanceValue(long id,String date){Cursor c=getReadableDatabase().rawQuery("SELECT present FROM attendance WHERE athleteId=? AND trainingDate=?",new String[]{""+id,date});boolean p=!c.moveToFirst()||c.getInt(0)==1;c.close();return p;}public Cursor absentOver10Days(){return getReadableDatabase().rawQuery("SELECT a.*,MAX(CASE WHEN at.present=1 THEN at.trainingDate END) lastPresent,MAX(at.trainingDate) lastAttendance FROM athletes a JOIN groups g ON g.name=a.groupName AND g.isSportsSchool=1 JOIN attendance at ON at.athleteId=a.id WHERE a.active=1 GROUP BY a.id HAVING lastAttendance IS NOT NULL AND (lastPresent IS NULL OR julianday('now')-julianday(lastPresent)>=10) ORDER BY a.name",null);}
 public Cursor inventory(){return getReadableDatabase().rawQuery("SELECT * FROM inventory ORDER BY name",null);}public void addInventoryItem(String n,int s,double b,double p){ContentValues v=new ContentValues();v.put("name",n);v.put("stock",s);v.put("buyPrice",b);v.put("sellPrice",p);getWritableDatabase().insertWithOnConflict("inventory",null,v,SQLiteDatabase.CONFLICT_IGNORE);}public void inventoryTx(long id,int q,String type,double b,double s,Long aid){ContentValues v=new ContentValues();v.put("itemId",id);v.put("txDate",iso.format(new Date()));v.put("qty",q);v.put("type",type);v.put("buyUnit",b);v.put("sellUnit",s);if(aid!=null)v.put("athleteId",aid);getWritableDatabase().insert("inventory_tx",null,v);getWritableDatabase().execSQL("UPDATE inventory SET stock=stock+? WHERE id=?",new Object[]{type.equals("IN")?q:-q,id});}public double inventoryProfit(String f,String t){Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(SUM(qty*(sellUnit-buyUnit)),0) FROM inventory_tx WHERE type='OUT' AND txDate BETWEEN ? AND ?",new String[]{f,t});c.moveToFirst();double x=c.getDouble(0);c.close();return x;}
}